vulnerable_code:
app.get('/api/orders/receipt/:id', async (req, res) => {
  const query = 'SELECT * FROM orders WHERE id = $1';
  const { rows } = await pgClient.query(query, [req.params.id]);
  if (rows.length === 0) return res.status(404).send();
  res.json(rows[0].receipt_details);
});

corrected_code:
app.get('/api/orders/receipt/:id', async (req, res) => {
  const query = 'SELECT * FROM orders WHERE id = $1 AND user_id = $2';
  const { rows } = await pgClient.query(query, [req.params.id, req.user.id]);
  if (rows.length === 0) return res.status(404).send();
  res.json(rows[0].receipt_details);
});
